   172→    encoded = ujson.dumps(s, ensure_ascii=False)
   173→
   174→    # json outputs an unicode object
   175→    encoded_json = json.dumps(s, ensure_ascii=False)
   176→    assert len(encoded) == len(s) + 2  # original length + quotes
   177→    assert encoded == encoded_json
   178→    decoded = ujson.loads(encoded)
   179→    assert s == decoded
