   542→static FASTCALL_ATTR INLINE_PREFIX void FASTCALL_MSVC Buffer_AppendCharUnchecked(JSONObjectEncoder *enc, char chr)
   543→{
   544→#ifdef DEBUG
   545→  if (enc->end <= enc->offset)
   546→  {
   547→    fprintf(stderr, "Overflow writing byte %d '%c'. The last few characters were:\n'''", chr, chr);
   548→    char * recent = enc->offset - 1000;
   549→    if (enc->start > recent)
   550→    {
   551→      recent = enc->start;
   552→    }
   553→    for (; recent < enc->offset; recent++)
   554→    {
   555→      fprintf(stderr, "%c", *recent);
   556→    }
   557→    fprintf(stderr, "'''\n");
   558→    abort();
   559→  }
   560→#endif
   561→  *(enc->offset++) = chr;
   562→}
