================================================================================

  ujson.encode(obj, **kwargs) -> str        [alias: ujson.dumps]
  ujson.decode(obj) -> Any                  [alias: ujson.loads]
  ujson.dump(obj, fp, **kwargs) -> None
  ujson.load(fp) -> Any

