  encode_html_chars: bool   - Encode <, >, & (default False)
  escape_forward_slashes: bool - Escape / (default True)
  sort_keys: bool           - Sort dictionary keys (default False)
  indent: int               - Indentation spaces (default 0)
  allow_nan: bool           - Allow NaN/Infinity (default True)
